/**
 * MiSans Latin faces, embedded as data URIs.
 *
 * Generated from misans@4.1.0/lib/Latin/MiSansLatin-*.woff2 (Apache-2.0; the
 * licence text ships in LICENSES/MiSans.txt). Three faces cover the chrome:
 * 400 body (the Medium file, declared as regular so the UI keeps the weight the
 * approved target image showed), 600 buttons and panel titles (Semibold), and
 * 700 headings (Bold). The upstream Regular file is 330; a 400 request would
 * skip it for the 500 face anyway, so shipping it would only add bytes that the
 * browser never paints.
 *
 * Why embedded rather than fetched: this skin is a desktop package, and a
 * security workstation may be offline or air-gapped. A CDN dependency would
 * also mean every launch makes a third-party request for a font. The three
 * Latin files are about 166 KB together, which is small enough to carry.
 *
 * Only Latin is vendored on purpose. The CJK half of MiSans is about 45 MB of
 * sharded woff2; the neon recipe keeps Chinese on the user's own font stack
 * instead of forcing that download on everyone. The family sits FIRST in the
 * neon stack so Latin glyphs use it; CJK falls through to the user's setting.
 *
 * Do not hand-edit the base64 below. Regenerate with the same three files if
 * the upstream package changes. No backticks in this file: styles.ts embeds
 * this string in a template literal.
 */

export const MISANS_LATIN_FACES = `
@font-face{font-family:'MiSans Latin';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'MiSans Latin';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'MiSans Latin';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
`
